const shield='<img class="brand-icon" src="./scam-alert-icon.png" alt="">';
const S={page:'setup',auto:false,bankConsent:false,consent:false,enabled:false,paused:false,sound:true,vibration:true,language:'English',scenario:'government',step:0,callActive:false,message:'',result:[],reportFrom:'call',reportBack:'warning',selected:{identity:true,reasons:true,excerpt:false},excerpt:'',additional:'',report:null,feedback:null,feedbackShared:false};
const job='Your application is approved. Pay a registration fee today to activate your job account. Do not discuss this offer with anyone.';
const normal='Thank you for applying. Please choose an interview slot through our careers website. No payment is required.';
const scenes={government:{title:'Government impersonation',format:'Supported call',cues:[['Caller','Hello, I am calling about a case linked to your identity. Can you confirm you have a moment?'],['Caller','This is urgent. Do not speak to your family or your bank about this investigation.'],['Caller','Transfer your savings to our safe account now so we can protect them.']],reasons:[['Payment demand','The caller asks you to move savings to a “safe account”.'],['Secrecy and pressure','Urgency is combined with instructions not to seek advice.']]},investment:{title:'Investment conversation',format:'Supported conversation',cues:[['Sender','Our private group has a new investment opportunity. Would you like to learn more?'],['Sender','A few places remain. People in this group have already received returns.'],['Sender','Guaranteed returns. Deposit today to secure your allocation, and keep this offer within our group.']],reasons:[['Payment pressure','An immediate deposit is requested alongside an assurance of returns.'],['Secrecy','The sender discourages discussing the offer outside the group.']]}};
const info={languages:['Language previews','Sample warning wording demonstrates the intended interface. Language detection and translation quality are not validated.'],setup:['Informed activation','Coverage and consent are explained before enabling protection. The consent control gates activation.'],dashboard:['Coverage is visible','The dashboard distinguishes supported call analysis from voluntary message checking. Pausing live analysis keeps manual checking available.'],scenarios:['Different scenarios, different reasons','Try explicit impersonation, gradually developing investment pressure, a job-scam message or a legitimate interaction. These are demonstrations, not test results.'],conversation:['Context develops over time','A normal opening is not proof of fraud. Later requests introduce urgency, secrecy and payment demands. The next-stage controls simulate this progression.'],warning:['An actionable explanation','The warning identifies specific suspicious requests and preserves the user’s choice. No transfer is automatically blocked.'],ongoing:['Choice without losing context','Continuing dismisses the immediate warning while the simulated interaction remains active. The warning can be reopened.'],ended:['Temporary processing ends','The call ends in this demonstration. Working call content would be discarded when no longer needed. Reports remain separate.'],message:['Voluntary message checking','Type or paste text, or load an example. The demonstration runs simple local checks and never transmits entered content.'],result:['An honest assessment','Explain indicators rather than invent an accuracy percentage. A result with no strong indicators is not a guarantee of safety.'],report:['Review before sharing','Select identity details, reasons and an optional excerpt. Unselected fields are excluded from the simulated report.'],confirmation:['Submission transparency','This screen displays the exact selected fields. No real reporting service is contacted.'],feedback:['Feedback with consent','A response can be reviewed before it is recorded in this browser session. It does not automatically retrain a model.'],feedbackReview:['Review optional feedback','Only the chosen response is included; audio, messages and transcripts are not attached.'],feedbackDone:['A separate feedback path','Feedback and reporting are distinct. The prototype records this response only in memory.'],settings:['Meaningful user controls','Pause live protection, set alert preferences and choose the language for the whole interface.'],coverage:['A visible limitation','The assistant cannot assume access to every call or messaging app. Channel limitations are shown rather than hidden.'],bank:['A conditional partner feature','An advisory banking-stage warning assumes an agreed integration. This prototype has no access to banking activity.']};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(s,a,kind='',extra='')=>`<button class="btn ${kind}" data-action="${a}" ${extra}>${s}</button>`;
const card=(t,b,kind='')=>`<div class="card ${kind}"><h3>${t}</h3><p>${b}</p></div>`;
const note=s=>`<p class="footnote">${s}</p>`;
const jump=(p,s)=>btn(s,'nav','outline',`data-page="${p}"`);
function go(page){stopAuto();S.page=page;location.hash=page;render();document.querySelector('.phone').scrollIntoView({behavior:'smooth',block:'nearest'});}
function toast(t){const e=document.getElementById('toast');e.className='toast';e.textContent=t;clearTimeout(toast.timer);toast.timer=setTimeout(()=>{e.className='';e.textContent=''},2800)}
function header(){return `<div class="phonebrand">${shield}Scam alert${S.page!=='setup'?'<button class="back" data-action="nav" data-page="dashboard">Home</button>':''}</div>`}
function title(t,s=''){return `<h2>${t}</h2>${s?`<p class="sub">${s}</p>`:''}`}
let demoTimer=null;
function stopAuto(){clearTimeout(demoTimer);demoTimer=null;S.auto=false;}
function scheduleAuto(){clearTimeout(demoTimer);demoTimer=setTimeout(()=>{if(!S.auto||S.page!=='conversation')return;if(S.step<2){S.step++;render();scheduleAuto()}else{go('warning')}},4200);}
function startScenario(which){if(!S.enabled||S.paused){toast('Enable or resume protection to try a supported live conversation.');go(S.enabled?'settings':'setup');return}S.scenario=which;S.step=0;S.callActive=true;go('conversation')}
function prepareReport(from,back){S.reportFrom=from;S.reportBack=back;S.selected={identity:true,reasons:true,excerpt:false};S.additional='';S.excerpt=from==='message'?S.message:'';go('report')}
function currentReasons(){return S.reportFrom==='message'?S.result:scenes[S.scenario].reasons}
function render(){let html=header();let sc=scenes[S.scenario];switch(S.page){
case 'setup':html+=title('Stay alert to<br>possible scams','Get warnings when supported conversations show suspicious requests or pressure.');html+=card('On-device analysis','Supported content is analysed on this phone.')+card('Clear explanations','Understand which requests may be suspicious.')+card('You stay in control','Continue, end the interaction or report.');html+=`<div class="notice">Protection works only with supported calls and messages. Permissions and authorised integration are required.</div><label class="consent"><input id="consent" type="checkbox" ${S.consent?'checked':''}>I understand the coverage and agree to enable protection.</label>`+btn('Enable protection','enable','',S.consent?'':'disabled')+`<button class="textbtn" data-action="nav" data-page="dashboard">Not now · explore the dashboard</button>`+note('Warnings may miss scams or flag legitimate conversations.');break;
case 'dashboard':html+=title('Your protection','A clear view of what is covered.');html+=card(!S.enabled?'Protection is off':S.paused?'Protection paused':'Protection enabled',!S.enabled?'Enable protection to try supported live-call scenarios.':S.paused?'Live analysis is paused. Manual message checking is still available.':'Analysis is enabled for supported channels in this demo.');html+=card('Supported calls','Requires an authorised calling integration. Coverage varies by channel.','plain');html+=btn('Try a demonstration','nav','', 'data-page="scenarios"')+jump('message','Check a message')+jump('coverage','View channel coverage');if(!S.enabled)html+=jump('setup','Enable protection');html+=note('No warning does not guarantee that an interaction is safe.');break;
case 'scenarios':html+=title('Try a demonstration','Different situations. Specific explanations.');html+='<div class="notice">All conversations are fictional. Staged warnings illustrate the design, not measured model performance.</div>';html+=`<button class="scenario" data-action="scenario" data-kind="government"><strong>Government impersonation call →</strong><small>Routine opening → secrecy → “safe account” transfer</small></button><button class="scenario" data-action="scenario" data-kind="investment"><strong>Investment conversation →</strong><small>Opportunity → trust building → urgent deposit</small></button><button class="scenario" data-action="load-job"><strong>Job-scam message →</strong><small>Upfront fee, urgency and secrecy</small></button><button class="scenario" data-action="load-normal"><strong>Legitimate recruitment message →</strong><small>Interview invitation without a payment request</small></button><button class="scenario" data-action="nav" data-page="bank"><strong>Optional banking-stage warning →</strong><small>Conditional partner-integration concept</small></button>`;break;
case 'conversation':html+=title(sc.title,`${sc.format} · Step ${S.step+1} of 3`)+`<div class="steps">${[0,1,2].map(i=>`<span class="${i<=S.step?'on':''}"></span>`).join('')}</div>`;html+=sc.cues.slice(0,S.step+1).map(([who,s])=>`<div class="chat"><div class="speaker">${who}</div>${esc(s)}</div>`).join('');html+=S.step===0?card('Assessing context','An opening alone does not establish fraud. Assessment continues.'):S.step===1?card('Stay alert · emerging concern','The conversation is changing. The next request adds context.','warning'):card('Pause and verify · high concern','Payment pressure is now combined with other suspicious behaviours.','warning');html+=`<div class="analysis-panel"><span class="kicker">Illustrative hybrid analysis</span><p><strong>Known-indicator check:</strong> ${S.step<2?'No decisive indicator in this scripted stage.':'High-risk payment wording identified.'}</p><p><strong>Conversation context:</strong> ${S.step===0?'Routine opening. Continue assessing.':S.step===1?'Stay alert: pressure is emerging.':'Pause and verify: payment pressure combines with secrecy.'}</p></div>`+btn(S.auto?'Pause automatic demo':'Play automatic demo',S.auto?'auto-pause':'auto-play','outline')+btn(S.step<2?'Next conversation stage':'Show warning','advance')+btn('End simulated interaction','end','outline');html+=note('A real system might warn earlier. These stages explain the proposed mechanism.');break;
case 'warning':html+=title('Pause and verify',`${sc.title} · Interaction in progress`)+`<span class="chip">${esc(sc.format)}</span>`+card('Why this was flagged',sc.reasons.map(([a,b])=>`<strong>${esc(a)}</strong><br>${esc(b)}`).join('<br><br>'),'warning')+card('Verify independently','Pause before acting. Contact the organisation through its official website or a trusted contact channel.','plain');html+=btn('End interaction','end','danger')+btn('Continue interaction','continue','outline')+btn('Review report','report','outline');if(S.bankConsent)html+=jump('bank','Preview payment reminder');html+=note('A warning is not proof of a scam. No transfer has been blocked.');break;
case 'ongoing':html+=title('Interaction in progress','You chose to continue.');html+=card('Stay alert','Supported protection continues in this simulated conversation.')+card('Before acting','Verify requests independently before paying or sharing sensitive information.','plain');html+=jump('warning','View warning')+btn('End interaction','end','danger')+btn('Review report','report','outline');break;
case 'ended':html+='<div class="success-icon">✓</div>'+title('Interaction ended','The simulated interaction has stopped.');html+=card('Temporary processing','Working call audio and transcripts would be discarded when no longer required.')+btn('Review report','report')+(S.bankConsent?jump('bank','Preview payment reminder'):'')+jump('feedback','Give warning feedback')+jump('dashboard','Back to dashboard');break;
case 'message':html+=title('Check a message','Paste or type suspicious text for an illustrative assessment.');html+=card('Before pasting','Remove passwords, OTPs and unnecessary personal details.')+`<label class="fieldlabel" for="messageText">Message text</label><textarea id="messageText" placeholder="Paste the message here…">${esc(S.message)}</textarea><p class="error" id="msgError"></p>`+btn('Analyse message','analyse','',S.message.trim()?'':'disabled')+`<div style="display:flex;gap:8px">${btn('Load scam example','load-job','outline')}${btn('Load legitimate example','load-normal','outline')}</div><button class="textbtn" data-action="clear-message">Clear message</button>`;break;
case 'result':html+=title(S.result.length?'Potential scam<br>indicators detected':'No strong scam<br>indicators detected','Illustrative local assessment');html+=S.result.length?S.result.map(([a,b])=>card(esc(a),esc(b),'warning')).join(''):card('What this means','The demonstration rules found no strong match. This is not evidence that the message is legitimate.');html+=card('Verify independently','Check the sender and request through an official channel before paying or sharing details.','plain');if(S.result.length)html+=btn('Review report','message-report');html+=jump('feedback','Give assessment feedback')+jump('message','Check another message')+note('An absence of indicators does not guarantee safety.');break;
case 'report':html+=title('Review your report','Choose what to include. Nothing is shared automatically.');html+=`<label class="report-field"><input data-report="identity" type="checkbox" ${S.selected.identity?'checked':''}><span><strong>Caller or sender details</strong><small>${S.reportFrom==='call'?'Unknown caller · identifier not available':'Message sender · identifier not supplied'}</small></span></label><label class="report-field"><input data-report="reasons" type="checkbox" ${S.selected.reasons?'checked':''}><span><strong>Warning reasons</strong><small>${currentReasons().map(r=>esc(r[0])).join(' · ')||'No strong indicators detected'}</small></span></label><label class="report-field"><input data-report="excerpt" type="checkbox" ${S.selected.excerpt?'checked':''}><span><strong>Include an excerpt (optional)</strong><small>Review and remove personal details. No audio is attached.</small></span></label>`;if(S.selected.excerpt)html+=`<label class="fieldlabel" for="excerpt">Reviewed excerpt</label><textarea id="excerpt" placeholder="Type the excerpt you choose to include">${esc(S.excerpt)}</textarea>`;html+=`<label class="fieldlabel" for="additional">Additional details (optional)</label><textarea id="additional" style="min-height:70px" placeholder="Add relevant context">${esc(S.additional)}</textarea>`+card('Demonstration destination','Prototype review only. No police, bank or external service receives this report.')+btn('Confirm simulated submission','submit-report')+btn('Cancel','cancel-report','outline')+note('Reporting does not automatically end an active interaction.');break;
case 'confirmation':html+='<div class="success-icon">✓</div>'+title('Report submitted','Simulated confirmation · no real report was sent.');let fields=[];if(S.report?.identity)fields.push('Caller or sender details');if(S.report?.reasons)fields.push('Warning reasons');if(S.report?.excerpt)fields.push('Reviewed excerpt');if(S.report?.additional)fields.push('Additional details');html+=card('Included in this demo',fields.length?fields.map(esc).join('<br>'):'No optional fields selected.');if(S.report?.excerpt)html+=card('Your reviewed excerpt',`<span data-user-content>${esc(S.report.excerpt)}</span>`,'plain');html+=note(S.callActive?'The simulated interaction is still active.':'No interaction is active.')+jump('feedback','Give warning feedback')+jump(S.callActive?'ongoing':'dashboard',S.callActive?'Return to interaction':'Back to dashboard');break;
case 'feedback':html+=title('Was this helpful?','Your feedback is optional and separate from reporting.');html+=card('What would be shared','Only your selected response. No call audio, transcript or message text is attached.');html+=['Helpful','Seems incorrect','Not sure'].map(s=>btn(s,'feedback-choice','outline',`data-value="${s}"`)).join('')+jump('dashboard','Skip');break;
case 'feedbackReview':html+=title('Review your feedback','Confirm before recording your response.');html+=card('Your response',esc(S.feedback))+card('Separate from model training','Feedback would be reviewed before informing future improvements. It would not automatically retrain a model.','plain')+btn('Confirm feedback','feedback-submit')+jump('feedback','Cancel')+note('This demo records feedback only in browser memory.');break;
case 'feedbackDone':html+='<div class="success-icon">✓</div>'+title('Feedback recorded','Thank you for reviewing the assessment.');html+=card('Response',esc(S.feedback))+note('No feedback was transmitted. Your response exists only in this browser session.')+jump('dashboard','Back to dashboard');break;
case 'settings':html+=title('','Control how supported protection works.');html+=`<label class="toggle"><span><strong>Supported live protection</strong><br><small>${!S.enabled?'Enable with consent first':S.paused?'Paused':'Enabled for supported channels'}</small></span><input id="protectToggle" type="checkbox" ${S.enabled&&!S.paused?'checked':''}></label><label class="toggle"><span>Sound alerts</span><input id="sound" type="checkbox" ${S.sound?'checked':''}></label><label class="toggle"><span>Vibration alerts</span><input id="vibration" type="checkbox" ${S.vibration?'checked':''}></label><label class="fieldlabel" for="language">Preferred language</label><select id="language">${['English','Mandarin','Malay','Tamil'].map(s=>`<option value="${s}" ${S.language===s?'selected':''}>${nativeNames[s]}</option>`).join('')}</select>`+note('Interface language changes throughout the demo. Detection uses illustrative rules, not a multilingual AI model.')+card('Temporary processing','Working audio and transcripts would be discarded when no longer required.')+card('Optional reporting','Select and review information before a simulated submission.')+`<label class="toggle"><span><strong>Optional payment reminder</strong><br><small>Separate opt-in. Simulates an agreed bank integration.</small></span><input id="bankConsent" type="checkbox" ${S.bankConsent?'checked':''}></label>`+card('Protection updates','Proposed release process: reviewed model and scam-list updates. No model or updates are downloaded in this demonstration.')+jump('languages','Preview warning languages')+btn('Save preferences','save-settings')+jump('coverage','View channel coverage');break;
case 'languages':html+=title('Warnings people understand','Illustrative language previews · translations require review before use.');html+=card('English','Pause before paying. Verify this request through an official channel.');html+=card('中文','付款前请暂停。请通过官方渠道核实这项要求。');html+=card('Bahasa Melayu','Berhenti seketika sebelum membuat bayaran. Sahkan permintaan ini melalui saluran rasmi.');html+=card('தமிழ்','பணம் செலுத்தும் முன் சற்று நிறுத்துங்கள். அதிகாரப்பூர்வ வழியில் இந்தக் கோரிக்கையைச் சரிபார்க்கவும்.');html+=card('Singlish scenario','“Must transfer now, cannot tell anyone lah.” The concern is the combined payment pressure and secrecy, not the use of Singlish.','warning')+jump('settings','Back to settings')+note('These previews do not demonstrate multilingual model performance.');break;
case 'coverage':html+=title('Know your coverage','Support depends on permissions and integration.');html+=card('Supported calling integration','Available only when authorised access to the call content is provided.','plain')+card('Other apps or call channels','Live analysis may be unavailable. This demo cannot access actual calls.','warning')+card('Voluntary message checking','You can submit message text manually for a separate assessment.')+jump('message','Check a message instead')+jump('dashboard','Back to dashboard')+note('Do not assume an unsupported interaction has been checked.');break;
case 'bank':html+=title('Pause before paying','Optional bank-partner integration · concept only');html+=card('Recent conversation risk','A supported conversation involved secrecy and pressure to transfer money.','warning')+card('Verify the request','Use an official contact channel before proceeding with a payment.','plain')+card('Your decision stays yours','This assistant has not blocked a transfer or accessed a bank account.')+(S.bankConsent?jump('scenarios','Return to demonstrations'):jump('settings','Review payment reminder opt-in'))+note('Requires separate user agreement and an agreed bank integration. No banking or payment function exists in this prototype.');break;
default:S.page='dashboard';render();return;}
html+='<div class="spacer"></div>';document.getElementById('screen').innerHTML=html;document.getElementById('screenName').textContent=S.page.replace(/([A-Z])/g,' $1');let d=info[S.page]||info.dashboard;document.getElementById('explainTitle').textContent=d[0];document.getElementById('explainBody').textContent=d[1];document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.page===S.page));}
function assess(s){const r=[];let t=s.toLowerCase();const aliases=[[/安全账户|akaun selamat|பாதுகாப்புக் கணக்க/gu,' safe account '],[/注册费|yuran pendaftaran|பதிவுக் கட்டணம்/gu,' registration fee '],[/立即|今天|紧急|segera|hari ini|உடனே|இன்றே|அவசரம்/gu,' urgent '],[/不要与|不要向|保密|jangan (bincang|beritahu)|rahsiakan|யாரிடமும் பேசாதீர்கள்|பேசாதீர்கள்|இரகசிய/gu,' secret '],[/保证回报|pulangan dijamin|உறுதியான வருமானம்/gu,' guaranteed returns '],[/密码|kata laluan|கடவுச்சொல்/gu,' password ']];for(const [pattern,token] of aliases)t=t.replace(pattern,token);if(/safe account/.test(t))r.push(['“Safe account” transfer','The message asks for a transfer to an account presented as protecting your money.']);if(/registration fee|pay.{0,25}(fee|activate)|upfront|gift card/.test(t))r.push(['Upfront or unusual payment','A fee or unusual payment method is requested as part of the opportunity.']);if(/urgent|today|immediately|right now|act now/.test(t))r.push(['Urgency','The wording pressures you to act quickly.']);if(/secret|do not (tell|discuss|speak)|don.t tell|keep.{0,25}(group|between)/.test(t))r.push(['Secrecy','The sender discourages discussing the request or getting independent advice.']);if(/guaranteed.{0,20}return/.test(t))r.push(['Assurance of returns','An investment return is presented as guaranteed.']);if(/(share|send|provide|tell).{0,25}(otp|password|pin)/.test(t))r.push(['Sensitive credentials','The message requests sensitive authentication information.']);return r;}
document.addEventListener('input',e=>{if(e.target.id==='messageText'){S.message=e.target.value;const b=document.querySelector('[data-action="analyse"]');if(b)b.disabled=!S.message.trim();}if(e.target.id==='excerpt')S.excerpt=e.target.value;if(e.target.id==='additional')S.additional=e.target.value;});
document.addEventListener('change',e=>{let t=e.target;if(t.id==='consent'){S.consent=t.checked;render();}if(t.dataset.report){S.selected[t.dataset.report]=t.checked;render();}if(t.id==='protectToggle'){if(!S.enabled){go('setup');return}S.paused=!t.checked;toast(S.paused?'Live protection paused':'Live protection resumed');render();}if(t.id==='bankConsent')S.bankConsent=t.checked;if(t.id==='sound')S.sound=t.checked;if(t.id==='vibration')S.vibration=t.checked;if(t.id==='language'||t.id==='globalLanguage'){const sampleKey=[job,normal].find(v=>S.message===v||translations[v]?.includes(S.message));S.language=t.value;if(sampleKey)S.message=tr(sampleKey);try{localStorage.setItem('scam-alert-language',S.language)}catch{}render();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;switch(a){case 'nav':go(b.dataset.page);break;case 'enable':if(S.consent){S.enabled=true;S.paused=false;go('dashboard')}break;case 'scenario':startScenario(b.dataset.kind);break;case 'auto-play':S.auto=true;render();scheduleAuto();break;case 'auto-pause':stopAuto();render();break;case 'advance':stopAuto();if(S.step<2){S.step++;render()}else go('warning');break;case 'end':stopAuto();S.callActive=false;S.step=0;go('ended');break;case 'continue':go('ongoing');break;case 'report':prepareReport('call',S.page);break;case 'message-report':prepareReport('message','result');break;case 'load-job':S.message=tr(job);go('message');break;case 'load-normal':S.message=tr(normal);go('message');break;case 'clear-message':S.message='';render();break;case 'analyse':if(!S.message.trim()){toast('Enter a message first');return}S.result=assess(S.message);go('result');break;case 'cancel-report':go(S.reportBack);break;case 'submit-report':if(S.selected.excerpt&&!S.excerpt.trim()){toast('Enter a reviewed excerpt or unselect that field.');return}S.report={identity:S.selected.identity,reasons:S.selected.reasons,excerpt:S.selected.excerpt?S.excerpt.trim():'',additional:S.additional.trim()};go('confirmation');break;case 'feedback-choice':S.feedback=b.dataset.value;go('feedbackReview');break;case 'feedback-submit':S.feedbackShared=true;go('feedbackDone');break;case 'save-settings':toast('Preferences saved for this browser session');go('dashboard');break;case 'reset':if(confirm('Restart the demonstration and clear session content?'))location.href=location.pathname+location.search;break;case 'download':{const html='<!doctype html>\n'+document.documentElement.outerHTML;const blob=new Blob([html],{type:'text/html'});const url=URL.createObjectURL(blob);const x=document.createElement('a');x.href=url;x.download='scam-alert-prototype.html';x.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(info[p]&&p!==S.page){S.page=p;render()}});
const translations={"Interface language":["界面语言","Bahasa antara muka","இடைமுக மொழி"],"Scam Alert": ["防诈骗提醒", "Amaran Penipuan", "மோசடி எச்சரிக்கை"], "Restart": ["重新开始", "Mula semula", "மீண்டும் தொடங்கு"], "Interactive concept · simulated": ["互动概念 · 模拟", "Konsep interaktif · simulasi", "ஊடாடும் கருத்தாக்கம் · உருவகப்படுத்தல்"], "The proposed experience": ["拟议使用体验", "Pengalaman yang dicadangkan", "முன்மொழியப்பட்ட அனுபவம்"], "A moment to pause.": ["停一停。", "Berhenti seketika.", "சற்று நிறுத்துங்கள்."], "A chance to verify.": ["先核实。", "Peluang untuk mengesahkan.", "சரிபார்க்க ஒரு வாய்ப்பு."], "Explore an on-device scam-warning assistant designed around clear explanations and user choice.": ["体验注重清晰解释和用户选择的设备端防诈骗助手。", "Terokai pembantu amaran penipuan pada peranti dengan penjelasan jelas dan pilihan pengguna.", "தெளிவான விளக்கங்களும் பயனர் தேர்வுகளும் கொண்ட சாதன மோசடி எச்சரிக்கை உதவியாளரை அறியுங்கள்."], "Prototype sections": ["原型部分", "Bahagian prototaip", "முன்மாதிரி பகுதிகள்"], "Get started": ["开始使用", "Mula", "தொடங்குங்கள்"], "Protection dashboard": ["防护概览", "Papan pemuka perlindungan", "பாதுகாப்பு முகப்பு"], "Try scenarios": ["体验情境", "Cuba senario", "சூழல்களை முயலுங்கள்"], "Check a message": ["检查信息", "Semak mesej", "செய்தியைச் சரிபார்க்கவும்"], "Privacy & settings": ["隐私与设置", "Privasi dan tetapan", "தனியுரிமையும் அமைப்புகளும்"], "Made for a proposal, not a real service.": ["用于提案展示，并非真实服务。", "Dibina untuk cadangan, bukan perkhidmatan sebenar.", "முன்மொழிவுக்காக உருவாக்கப்பட்டது; உண்மையான சேவை அல்ல."], "Fictional conversations. No calls, payments, reports or feedback are sent. Message checks use illustrative local rules, not a trained AI model.": ["对话为虚构。不会发送通话、付款、举报或反馈。信息检查采用本地示例规则，并非经过训练的人工智能模型。", "Perbualan rekaan. Tiada panggilan, bayaran, laporan atau maklum balas dihantar. Semakan mesej menggunakan peraturan contoh setempat, bukan model AI terlatih.", "கற்பனை உரையாடல்கள். அழைப்புகள், பணம், புகார்கள் அல்லது கருத்துகள் அனுப்பப்படுவதில்லை. செய்திச் சோதனை உள்ளூர் எடுத்துக்காட்டு விதிகளைப் பயன்படுத்துகிறது; பயிற்சிபெற்ற AI மாதிரியை அல்ல."], "Interactive demo": ["互动演示", "Demo interaktif", "ஊடாடும் செயல்விளக்கம்"], "Click through the controls. All activity remains in this browser session.": ["点击操作体验。所有活动仅保留在本次浏览器会话中。", "Cuba kawalan yang tersedia. Semua aktiviti kekal dalam sesi pelayar ini.", "கட்டுப்பாடுகளை முயலுங்கள். எல்லாச் செயல்களும் இந்த உலாவி அமர்வில் மட்டுமே இருக்கும்."], "Behind this screen": ["界面说明", "Di sebalik skrin", "இந்தத் திரையின் பின்னணி"], "Design principles": ["设计原则", "Prinsip reka bentuk", "வடிவமைப்புக் கொள்கைகள்"], "Explain the concern": ["解释风险原因", "Jelaskan kebimbangan", "கவலைக்கான காரணத்தை விளக்குதல்"], "Specific behaviours, not a mysterious risk score.": ["指出具体行为，而非难以理解的风险分数。", "Tingkah laku khusus, bukan skor risiko yang tidak jelas.", "குறிப்பிட்ட நடத்தைகள்; புரியாத இடர் மதிப்பெண் அல்ல."], "Keep users in control": ["由用户掌控", "Pengguna kekal mengawal", "பயனரின் கட்டுப்பாடு"], "Continue, leave or review a report.": ["继续、退出或检查举报内容。", "Teruskan, tamatkan atau semak laporan.", "தொடரவும், வெளியேறவும் அல்லது புகாரை மதிப்பாய்வு செய்யவும்."], "Minimise shared content": ["尽量减少共享内容", "Minimumkan kandungan dikongsi", "பகிரப்படும் தகவலைக் குறைத்தல்"], "Review details before a simulated submission.": ["模拟提交前检查详情。", "Semak butiran sebelum penghantaran simulasi.", "உருவகச் சமர்ப்பிப்புக்கு முன் விவரங்களை மதிப்பாய்வு செய்யவும்."], "What this prototype does": ["原型功能说明", "Fungsi prototaip ini", "இந்த முன்மாதிரியின் செயல்கள்"], "Demonstrates interface behaviour and scenario flows. It does not validate detection accuracy, multilingual support or banking integration. No external model or reporting endpoint is called.": ["展示界面与情境流程，不验证检测准确率、多语言模型或银行集成。不会调用外部模型或举报服务。", "Menunjukkan antara muka dan aliran senario. Ketepatan pengesanan, model berbilang bahasa dan integrasi bank tidak disahkan. Tiada model luaran atau perkhidmatan laporan dipanggil.", "இடைமுகத்தையும் சூழல் ஓட்டங்களையும் காட்டுகிறது. கண்டறிதல் துல்லியம், பன்மொழி மாதிரி அல்லது வங்கி ஒருங்கிணைப்பு சரிபார்க்கப்படவில்லை. வெளிப்புற மாதிரியோ புகார் சேவையோ அழைக்கப்படுவதில்லை."], "Home": ["主页", "Utama", "முகப்பு"], "Scam alert": ["防诈骗提醒", "Amaran penipuan", "மோசடி எச்சரிக்கை"], "Stay alert to": ["保持警惕", "Berwaspada terhadap", "எச்சரிக்கையாக இருங்கள்"], "possible scams": ["可能的诈骗", "kemungkinan penipuan", "சாத்தியமான மோசடிகள்"], "Get warnings when supported conversations show suspicious requests or pressure.": ["受支持的对话出现可疑要求或施压时接收提醒。", "Terima amaran apabila perbualan disokong menunjukkan permintaan mencurigakan atau tekanan.", "ஆதரிக்கப்படும் உரையாடலில் சந்தேகக் கோரிக்கைகளோ அழுத்தமோ தோன்றும்போது எச்சரிக்கை பெறுங்கள்."], "On-device analysis": ["设备端分析", "Analisis pada peranti", "சாதனத்திலேயே பகுப்பாய்வு"], "Supported content is analysed on this phone.": ["受支持的内容在本手机上分析。", "Kandungan disokong dianalisis pada telefon ini.", "ஆதரிக்கப்படும் உள்ளடக்கம் இந்தத் தொலைபேசியிலேயே பகுப்பாய்வு செய்யப்படுகிறது."], "Clear explanations": ["清晰解释", "Penjelasan jelas", "தெளிவான விளக்கங்கள்"], "Understand which requests may be suspicious.": ["了解哪些要求可能可疑。", "Fahami permintaan yang mungkin mencurigakan.", "எந்தக் கோரிக்கைகள் சந்தேகமானவை எனப் புரிந்துகொள்ளுங்கள்."], "You stay in control": ["由您掌控", "Anda kekal mengawal", "கட்டுப்பாடு உங்களிடமே"], "Continue, end the interaction or report.": ["继续、结束互动或举报。", "Teruskan, tamatkan interaksi atau laporkan.", "தொடரவும், உரையாடலை முடிக்கவும் அல்லது புகாரளிக்கவும்."], "Protection works only with supported calls and messages. Permissions and authorised integration are required.": ["防护仅适用于受支持的通话和信息，需要权限及获授权的集成。", "Perlindungan hanya untuk panggilan dan mesej disokong. Kebenaran dan integrasi sah diperlukan.", "ஆதரிக்கப்படும் அழைப்புகளுக்கும் செய்திகளுக்கும் மட்டுமே பாதுகாப்பு. அனுமதிகளும் அங்கீகரிக்கப்பட்ட ஒருங்கிணைப்பும் தேவை."], "I understand the coverage and agree to enable protection.": ["我了解防护范围，并同意启用防护。", "Saya memahami liputan dan bersetuju mengaktifkan perlindungan.", "பாதுகாப்பு வரம்பைப் புரிந்துகொண்டு அதை இயக்க ஒப்புக்கொள்கிறேன்."], "Enable protection": ["启用防护", "Aktifkan perlindungan", "பாதுகாப்பை இயக்கவும்"], "Not now · explore the dashboard": ["暂不启用 · 浏览概览", "Bukan sekarang · lihat papan pemuka", "இப்போது வேண்டாம் · முகப்பைப் பார்க்கவும்"], "Warnings may miss scams or flag legitimate conversations.": ["提醒可能漏报诈骗，也可能误报正常对话。", "Amaran mungkin terlepas penipuan atau menandakan perbualan sah.", "எச்சரிக்கைகள் மோசடிகளைத் தவறவிடலாம் அல்லது முறையான உரையாடல்களைக் குறிக்கலாம்."], "Concept prototype · simulated interactions": ["概念原型 · 模拟互动", "Prototaip konsep · interaksi simulasi", "கருத்தாக்க முன்மாதிரி · உருவக உரையாடல்கள்"], "Your protection": ["您的防护", "Perlindungan anda", "உங்கள் பாதுகாப்பு"], "A clear view of what is covered.": ["清楚了解防护范围。", "Lihat liputan dengan jelas.", "பாதுகாப்பு வரம்பைத் தெளிவாக அறியுங்கள்."], "Protection is off": ["防护已关闭", "Perlindungan dimatikan", "பாதுகாப்பு முடக்கப்பட்டுள்ளது"], "Protection paused": ["防护已暂停", "Perlindungan dijeda", "பாதுகாப்பு இடைநிறுத்தப்பட்டது"], "Protection enabled": ["防护已启用", "Perlindungan diaktifkan", "பாதுகாப்பு இயக்கப்பட்டது"], "Enable protection to try supported live-call scenarios.": ["启用防护后可体验受支持的通话情境。", "Aktifkan perlindungan untuk mencuba senario panggilan disokong.", "ஆதரிக்கப்படும் அழைப்புச் சூழல்களை முயல பாதுகாப்பை இயக்கவும்."], "Live analysis is paused. Manual message checking is still available.": ["实时分析已暂停，仍可手动检查信息。", "Analisis langsung dijeda. Semakan mesej manual masih tersedia.", "நேரடிப் பகுப்பாய்வு இடைநிறுத்தப்பட்டது. கைமுறை செய்திச் சோதனை கிடைக்கிறது."], "Analysis is enabled for supported channels in this demo.": ["此演示已启用受支持渠道的分析。", "Analisis diaktifkan untuk saluran disokong dalam demo ini.", "இந்தச் செயல்விளக்கத்தில் ஆதரிக்கப்படும் வழிகளுக்குப் பகுப்பாய்வு இயக்கப்பட்டுள்ளது."], "Supported calls": ["受支持的通话", "Panggilan disokong", "ஆதரிக்கப்படும் அழைப்புகள்"], "Requires an authorised calling integration. Coverage varies by channel.": ["需要获授权的通话集成，范围因渠道而异。", "Memerlukan integrasi panggilan yang sah. Liputan berbeza mengikut saluran.", "அங்கீகரிக்கப்பட்ட அழைப்பு ஒருங்கிணைப்பு தேவை. வழிக்கேற்ப வரம்பு மாறுபடும்."], "Try a demonstration": ["体验演示", "Cuba demonstrasi", "செயல்விளக்கத்தை முயலுங்கள்"], "Protection and privacy": ["防护与隐私", "Perlindungan dan privasi", "பாதுகாப்பும் தனியுரிமையும்"], "View channel coverage": ["查看渠道覆盖范围", "Lihat liputan saluran", "வழிகளின் ஆதரவைப் பார்க்கவும்"], "No warning does not guarantee that an interaction is safe.": ["没有提醒并不保证互动安全。", "Tiada amaran tidak menjamin interaksi selamat.", "எச்சரிக்கை இல்லாதது உரையாடல் பாதுகாப்பானது என்பதற்கான உத்தரவாதம் அல்ல."], "Different situations. Specific explanations.": ["不同情境，具体解释。", "Situasi berbeza. Penjelasan khusus.", "வெவ்வேறு சூழல்கள். குறிப்பிட்ட விளக்கங்கள்."], "All conversations are fictional. Staged warnings illustrate the design, not measured model performance.": ["所有对话均为虚构。分阶段提醒用于展示设计，并非模型实测结果。", "Semua perbualan adalah rekaan. Amaran berperingkat menunjukkan reka bentuk, bukan prestasi model yang diukur.", "எல்லா உரையாடல்களும் கற்பனையானவை. படிநிலை எச்சரிக்கைகள் வடிவமைப்பைக் காட்டுகின்றன; அளவிடப்பட்ட மாதிரிச் செயல்திறனை அல்ல."], "Government impersonation call →": ["冒充政府人员的来电 →", "Panggilan penyamaran kerajaan →", "அரசு அதிகாரி போல நடிக்கும் அழைப்பு →"], "Routine opening → secrecy → “safe account” transfer": ["普通开场 → 要求保密 → 转账至“安全账户”", "Pembukaan biasa → kerahsiaan → pindahan “akaun selamat”", "சாதாரண தொடக்கம் → இரகசியம் → “பாதுகாப்புக் கணக்கு” பரிமாற்றம்"], "Investment conversation →": ["投资对话 →", "Perbualan pelaburan →", "முதலீட்டு உரையாடல் →"], "Opportunity → trust building → urgent deposit": ["投资机会 → 建立信任 → 催促存款", "Peluang → membina kepercayaan → deposit segera", "வாய்ப்பு → நம்பிக்கை உருவாக்கம் → அவசர வைப்புத்தொகை"], "Job-scam message →": ["求职诈骗信息 →", "Mesej penipuan pekerjaan →", "வேலை மோசடிச் செய்தி →"], "Upfront fee, urgency and secrecy": ["预付费用、催促及保密", "Yuran pendahuluan, desakan dan kerahsiaan", "முன்கட்டணம், அவசரம் மற்றும் இரகசியம்"], "Legitimate recruitment message →": ["正常招聘信息 →", "Mesej pengambilan pekerja sah →", "முறையான ஆட்சேர்ப்புச் செய்தி →"], "Interview invitation without a payment request": ["无需付款的面试邀请", "Jemputan temu duga tanpa permintaan bayaran", "பணம் கோராத நேர்முக அழைப்பு"], "Optional banking-stage warning →": ["可选的付款阶段提醒 →", "Amaran peringkat bank pilihan →", "விருப்ப வங்கிநிலை எச்சரிக்கை →"], "Conditional partner-integration concept": ["需合作集成的概念功能", "Konsep integrasi rakan kongsi bersyarat", "கூட்டாளர் ஒருங்கிணைப்பைச் சார்ந்த கருத்தாக்கம்"], "Government impersonation": ["冒充政府人员", "Penyamaran kerajaan", "அரசு அதிகாரி ஆள்மாறாட்டம்"], "Supported call": ["受支持的通话", "Panggilan disokong", "ஆதரிக்கப்படும் அழைப்பு"], "Caller": ["来电者", "Pemanggil", "அழைப்பாளர்"], "Hello, I am calling about a case linked to your identity. Can you confirm you have a moment?": ["您好，您的身份涉及一宗案件。现在方便说话吗？", "Helo, saya menelefon tentang kes yang berkaitan dengan identiti anda. Ada masa sebentar?", "வணக்கம், உங்கள் அடையாளத்துடன் தொடர்புடைய வழக்கு குறித்துப் பேசுகிறேன். சிறிது நேரம் உள்ளதா?"], "This is urgent. Do not speak to your family or your bank about this investigation.": ["情况紧急。不要向家人或银行透露这项调查。", "Ini segera. Jangan beritahu keluarga atau bank anda tentang siasatan ini.", "இது அவசரம். இந்த விசாரணையைப் பற்றி உங்கள் குடும்பத்திடமோ வங்கியிடமோ பேசாதீர்கள்."], "Transfer your savings to our safe account now so we can protect them.": ["立即把存款转到我们的安全账户，以便我们保护资金。", "Pindahkan simpanan anda ke akaun selamat kami sekarang supaya kami boleh melindunginya.", "உங்கள் சேமிப்பைப் பாதுகாக்க உடனே எங்கள் பாதுகாப்புக் கணக்கிற்கு மாற்றுங்கள்."], "Investment conversation": ["投资对话", "Perbualan pelaburan", "முதலீட்டு உரையாடல்"], "Supported conversation": ["受支持的对话", "Perbualan disokong", "ஆதரிக்கப்படும் உரையாடல்"], "Sender": ["发送者", "Pengirim", "அனுப்புநர்"], "Our private group has a new investment opportunity. Would you like to learn more?": ["我们的私人群组有一个新投资机会，想了解吗？", "Kumpulan peribadi kami ada peluang pelaburan baharu. Mahu tahu lebih lanjut?", "எங்கள் தனிப்பட்ட குழுவில் புதிய முதலீட்டு வாய்ப்பு உள்ளது. மேலும் அறிய விரும்புகிறீர்களா?"], "A few places remain. People in this group have already received returns.": ["名额不多了，群组里已经有人拿到回报。", "Tempat tinggal sedikit. Ahli kumpulan ini sudah menerima pulangan.", "சில இடங்களே உள்ளன. இந்தக் குழுவில் உள்ளவர்கள் ஏற்கெனவே வருமானம் பெற்றுள்ளனர்."], "Guaranteed returns. Deposit today to secure your allocation, and keep this offer within our group.": ["保证回报。今天存款保留名额，并将此优惠在群内保密。", "Pulangan dijamin. Buat deposit hari ini untuk menempah tempat, dan rahsiakan tawaran ini dalam kumpulan kita.", "உறுதியான வருமானம். உங்கள் இடத்தைப் பெற இன்றே பணம் செலுத்துங்கள்; இந்தச் சலுகையை நம் குழுவுக்குள் வைத்திருங்கள்."], "Assessing context": ["正在分析上下文", "Menilai konteks", "சூழல் மதிப்பிடப்படுகிறது"], "An opening alone does not establish fraud. Assessment continues.": ["仅凭开场不能判断诈骗，分析将继续。", "Pembukaan sahaja tidak membuktikan penipuan. Penilaian diteruskan.", "தொடக்கத்தை மட்டும் வைத்து மோசடி என முடிவுசெய்ய முடியாது. மதிப்பீடு தொடர்கிறது."], "Stay alert · emerging concern": ["保持警惕 · 初现风险", "Berwaspada · kebimbangan awal", "எச்சரிக்கையாக இருங்கள் · ஆரம்பக் கவலை"], "The conversation is changing. The next request adds context.": ["对话正在变化，下一个要求会提供更多线索。", "Perbualan sedang berubah. Permintaan seterusnya menambah konteks.", "உரையாடல் மாறுகிறது. அடுத்த கோரிக்கை கூடுதல் சூழலை வழங்கும்."], "Pause and verify · high concern": ["暂停并核实 · 高风险", "Berhenti dan sahkan · kebimbangan tinggi", "நிறுத்திச் சரிபார்க்கவும் · அதிகக் கவலை"], "Payment pressure is now combined with other suspicious behaviours.": ["付款压力现已与其他可疑行为同时出现。", "Tekanan bayaran kini digabungkan dengan tingkah laku mencurigakan lain.", "பணம் செலுத்தும் அழுத்தத்துடன் பிற சந்தேக நடத்தைகளும் இணைகின்றன."], "Illustrative hybrid analysis": ["混合分析示例", "Contoh analisis hibrid", "கலப்புப் பகுப்பாய்வு எடுத்துக்காட்டு"], "Known-indicator check:": ["已知指标检查：", "Semakan petunjuk diketahui:", "அறியப்பட்ட அறிகுறிச் சோதனை:"], "Conversation context:": ["对话上下文：", "Konteks perbualan:", "உரையாடல் சூழல்:"], "No decisive indicator in this scripted stage.": ["此脚本阶段没有决定性指标。", "Tiada petunjuk muktamad pada peringkat skrip ini.", "இந்தக் கற்பனைப் படிநிலையில் தீர்மானமான அறிகுறி இல்லை."], "High-risk payment wording identified.": ["发现高风险付款措辞。", "Kata-kata bayaran berisiko tinggi dikenal pasti.", "அதிக இடருள்ள பணக் கோரிக்கை கண்டறியப்பட்டது."], "Routine opening. Continue assessing.": ["普通开场，继续分析。", "Pembukaan biasa. Teruskan penilaian.", "சாதாரண தொடக்கம். மதிப்பீட்டைத் தொடரவும்."], "Stay alert: pressure is emerging.": ["保持警惕：开始出现施压。", "Berwaspada: tekanan mula muncul.", "எச்சரிக்கை: அழுத்தம் தோன்றுகிறது."], "Pause and verify: payment pressure combines with secrecy.": ["暂停并核实：付款压力伴随保密要求。", "Berhenti dan sahkan: tekanan bayaran disertai kerahsiaan.", "நிறுத்திச் சரிபார்க்கவும்: பண அழுத்தமும் இரகசியமும் இணைகின்றன."], "Pause automatic demo": ["暂停自动演示", "Jeda demo automatik", "தானியங்கி விளக்கத்தை இடைநிறுத்து"], "Play automatic demo": ["播放自动演示", "Mainkan demo automatik", "தானியங்கி விளக்கத்தை இயக்கு"], "Next conversation stage": ["下一对话阶段", "Peringkat perbualan seterusnya", "அடுத்த உரையாடல் படிநிலை"], "Show warning": ["显示提醒", "Papar amaran", "எச்சரிக்கையைக் காட்டு"], "End simulated interaction": ["结束模拟互动", "Tamatkan interaksi simulasi", "உருவக உரையாடலை முடி"], "A real system might warn earlier. These stages explain the proposed mechanism.": ["真实系统可能更早提醒。这些阶段用于解释拟议机制。", "Sistem sebenar mungkin memberi amaran lebih awal. Peringkat ini menerangkan mekanisme cadangan.", "உண்மையான அமைப்பு முன்னரே எச்சரிக்கலாம். இந்தப் படிநிலைகள் முன்மொழியப்பட்ட முறையை விளக்குகின்றன."], "Pause and verify": ["暂停并核实", "Berhenti dan sahkan", "நிறுத்திச் சரிபார்க்கவும்"], "Why this was flagged": ["为何发出提醒", "Sebab ini ditandakan", "இது குறிக்கப்பட்ட காரணம்"], "Payment demand": ["要求付款", "Permintaan bayaran", "பணக் கோரிக்கை"], "The caller asks you to move savings to a “safe account”.": ["来电者要求将存款转至“安全账户”。", "Pemanggil meminta anda memindahkan simpanan ke “akaun selamat”.", "அழைப்பாளர் சேமிப்பை “பாதுகாப்புக் கணக்கிற்கு” மாற்றச் சொல்கிறார்."], "Secrecy and pressure": ["保密与施压", "Kerahsiaan dan tekanan", "இரகசியமும் அழுத்தமும்"], "Urgency is combined with instructions not to seek advice.": ["催促立即行动，同时要求不要寻求建议。", "Desakan disertai arahan supaya tidak mendapatkan nasihat.", "அவசரத்துடன் ஆலோசனை கேட்க வேண்டாம் என்ற அறிவுறுத்தலும் உள்ளது."], "Payment pressure": ["付款压力", "Tekanan bayaran", "பணம் செலுத்தும் அழுத்தம்"], "An immediate deposit is requested alongside an assurance of returns.": ["以保证回报为由要求立即存款。", "Deposit segera diminta bersama jaminan pulangan.", "வருமான உறுதியுடன் உடனடி வைப்புத்தொகை கோரப்படுகிறது."], "Secrecy": ["要求保密", "Kerahsiaan", "இரகசியம்"], "The sender discourages discussing the offer outside the group.": ["发送者不鼓励与群外人士讨论。", "Pengirim menghalang perbincangan tawaran di luar kumpulan.", "குழுவுக்கு வெளியே சலுகையைப் பற்றிப் பேச வேண்டாம் என அனுப்புநர் கூறுகிறார்."], "Verify independently": ["独立核实", "Sahkan secara bebas", "சுயமாகச் சரிபார்க்கவும்"], "Pause before acting. Contact the organisation through its official website or a trusted contact channel.": ["行动前先暂停。通过官方网站或可信渠道联系该机构。", "Berhenti sebelum bertindak. Hubungi organisasi melalui laman rasmi atau saluran dipercayai.", "செயல்படுவதற்கு முன் நிறுத்துங்கள். அதிகாரப்பூர்வ இணையதளம் அல்லது நம்பகமான வழியில் நிறுவனத்தைத் தொடர்புகொள்ளுங்கள்."], "End interaction": ["结束互动", "Tamatkan interaksi", "உரையாடலை முடி"], "Continue interaction": ["继续互动", "Teruskan interaksi", "உரையாடலைத் தொடர்"], "Review report": ["检查举报内容", "Semak laporan", "புகாரை மதிப்பாய்வு செய்"], "Preview payment reminder": ["预览付款提醒", "Pratonton peringatan bayaran", "பண எச்சரிக்கை முன்னோட்டம்"], "A warning is not proof of a scam. No transfer has been blocked.": ["提醒并非诈骗的确证，也未阻止任何转账。", "Amaran bukan bukti penipuan. Tiada pindahan disekat.", "எச்சரிக்கை மோசடிக்கான ஆதாரம் அல்ல. எந்தப் பரிமாற்றமும் தடுக்கப்படவில்லை."], "Interaction in progress": ["互动进行中", "Interaksi berlangsung", "உரையாடல் நடைபெறுகிறது"], "You chose to continue.": ["您选择了继续。", "Anda memilih untuk meneruskan.", "நீங்கள் தொடரத் தேர்ந்தெடுத்தீர்கள்."], "Stay alert": ["保持警惕", "Berwaspada", "எச்சரிக்கையாக இருங்கள்"], "Supported protection continues in this simulated conversation.": ["此模拟对话的受支持防护继续运行。", "Perlindungan disokong diteruskan dalam perbualan simulasi ini.", "இந்த உருவக உரையாடலில் ஆதரிக்கப்படும் பாதுகாப்பு தொடர்கிறது."], "Before acting": ["行动之前", "Sebelum bertindak", "செயல்படுவதற்கு முன்"], "Verify requests independently before paying or sharing sensitive information.": ["付款或分享敏感资料前独立核实要求。", "Sahkan permintaan secara bebas sebelum membayar atau berkongsi maklumat sensitif.", "பணம் செலுத்தவோ முக்கியத் தகவலைப் பகிரவோ முன் கோரிக்கையைச் சுயமாகச் சரிபார்க்கவும்."], "View warning": ["查看提醒", "Lihat amaran", "எச்சரிக்கையைப் பார்"], "Interaction ended": ["互动已结束", "Interaksi ditamatkan", "உரையாடல் முடிந்தது"], "The simulated interaction has stopped.": ["模拟互动已停止。", "Interaksi simulasi telah berhenti.", "உருவக உரையாடல் நிறுத்தப்பட்டது."], "Temporary processing": ["临时处理", "Pemprosesan sementara", "தற்காலிகச் செயலாக்கம்"], "Working call audio and transcripts would be discarded when no longer required.": ["不再需要时将删除处理中的通话音频及文字记录。", "Audio panggilan dan transkrip kerja akan dipadam apabila tidak diperlukan.", "தேவை முடிந்ததும் செயலாக்க அழைப்பு ஒலியும் உரைப் பதிவுகளும் நீக்கப்படும்."], "Give warning feedback": ["反馈提醒体验", "Beri maklum balas amaran", "எச்சரிக்கை குறித்த கருத்து"], "Back to dashboard": ["返回概览", "Kembali ke papan pemuka", "முகப்பிற்குத் திரும்பு"], "Paste or type suspicious text for an illustrative assessment.": ["粘贴或输入可疑文字以体验示例分析。", "Tampal atau taip teks mencurigakan untuk penilaian contoh.", "எடுத்துக்காட்டு மதிப்பீட்டிற்குச் சந்தேக உரையை ஒட்டவும் அல்லது தட்டச்சு செய்யவும்."], "Before pasting": ["粘贴之前", "Sebelum menampal", "ஒட்டுவதற்கு முன்"], "Remove passwords, OTPs and unnecessary personal details.": ["删除密码、一次性密码及不必要的个人资料。", "Buang kata laluan, OTP dan butiran peribadi yang tidak diperlukan.", "கடவுச்சொற்கள், ஒருமுறைக் கடவுச்சொற்கள் மற்றும் தேவையற்ற தனிப்பட்ட விவரங்களை நீக்கவும்."], "Message text": ["信息内容", "Teks mesej", "செய்தி உரை"], "Paste the message here…": ["在此粘贴信息…", "Tampal mesej di sini…", "செய்தியை இங்கே ஒட்டவும்…"], "Analyse message": ["分析信息", "Analisis mesej", "செய்தியைப் பகுப்பாய்வு செய்"], "Load scam example": ["载入诈骗示例", "Muat contoh penipuan", "மோசடி எடுத்துக்காட்டை ஏற்று"], "Load legitimate example": ["载入正常示例", "Muat contoh sah", "முறையான எடுத்துக்காட்டை ஏற்று"], "Clear message": ["清除信息", "Kosongkan mesej", "செய்தியை அழி"], "This demo uses simple local rules, not a trained AI model. Entered text is not transmitted or saved after reload.": ["演示使用简单本地规则，并非经过训练的人工智能模型。输入内容不会发送，刷新后不保留。", "Demo ini menggunakan peraturan setempat mudah, bukan model AI terlatih. Teks tidak dihantar atau disimpan selepas muat semula.", "இந்த விளக்கம் எளிய உள்ளூர் விதிகளைப் பயன்படுத்துகிறது; பயிற்சிபெற்ற AI மாதிரியை அல்ல. உரை அனுப்பப்படாது; மீளேற்றியபின் சேமிக்கப்படாது."], "Potential scam": ["可能存在诈骗", "Kemungkinan penipuan", "சாத்தியமான மோசடி"], "indicators detected": ["检测到相关迹象", "petunjuk dikesan", "அறிகுறிகள் கண்டறியப்பட்டன"], "No strong scam": ["未发现明显诈骗", "Tiada petunjuk penipuan kukuh", "வலுவான மோசடி அறிகுறிகள் இல்லை"], "No strong indicators detected": ["未发现明显迹象", "Tiada petunjuk kukuh dikesan", "வலுவான அறிகுறிகள் இல்லை"], "Illustrative local assessment": ["本地分析示例", "Penilaian setempat contoh", "உள்ளூர் மதிப்பீட்டு எடுத்துக்காட்டு"], "What this means": ["结果含义", "Maksudnya", "இதன் பொருள்"], "The demonstration rules found no strong match. This is not evidence that the message is legitimate.": ["示例规则未发现明显匹配，不代表信息真实可信。", "Peraturan demo tidak menemui padanan kukuh. Ini bukan bukti bahawa mesej itu sah.", "விளக்க விதிகள் வலுவான பொருத்தத்தைக் காணவில்லை. இது செய்தி முறையானது என்பதற்கான ஆதாரம் அல்ல."], "Check the sender and request through an official channel before paying or sharing details.": ["付款或分享资料前，通过官方渠道核实发送者和要求。", "Semak pengirim dan permintaan melalui saluran rasmi sebelum membayar atau berkongsi butiran.", "பணம் செலுத்தவோ விவரங்களைப் பகிரவோ முன் அதிகாரப்பூர்வ வழியில் அனுப்புநரையும் கோரிக்கையையும் சரிபார்க்கவும்."], "Give assessment feedback": ["反馈分析体验", "Beri maklum balas penilaian", "மதிப்பீடு குறித்த கருத்து"], "Check another message": ["检查另一条信息", "Semak mesej lain", "மற்றொரு செய்தியைச் சரிபார்"], "An absence of indicators does not guarantee safety.": ["没有风险迹象不代表安全。", "Ketiadaan petunjuk tidak menjamin keselamatan.", "அறிகுறிகள் இல்லாதது பாதுகாப்பிற்கு உத்தரவாதம் அல்ல."], "Your application is approved. Pay a registration fee today to activate your job account. Do not discuss this offer with anyone.": ["您的申请已获批准。今天支付注册费以激活工作账户。不要与任何人讨论此机会。", "Permohonan anda diluluskan. Bayar yuran pendaftaran hari ini untuk mengaktifkan akaun kerja anda. Jangan bincangkan tawaran ini dengan sesiapa.", "உங்கள் விண்ணப்பம் ஏற்கப்பட்டது. வேலைக் கணக்கைச் செயல்படுத்த இன்றே பதிவுக் கட்டணம் செலுத்துங்கள். இந்த வாய்ப்பைப் பற்றி யாரிடமும் பேசாதீர்கள்."], "Thank you for applying. Please choose an interview slot through our careers website. No payment is required.": ["感谢申请。请通过我们的招聘网站选择面试时段。无需付款。", "Terima kasih kerana memohon. Pilih masa temu duga melalui laman kerjaya kami. Tiada bayaran diperlukan.", "விண்ணப்பித்ததற்கு நன்றி. எங்கள் வேலைவாய்ப்பு இணையதளத்தில் நேர்முக நேரத்தைத் தேர்ந்தெடுக்கவும். பணம் செலுத்தத் தேவையில்லை."], "Review your report": ["检查您的举报", "Semak laporan anda", "உங்கள் புகாரை மதிப்பாய்வு செய்யவும்"], "Choose what to include. Nothing is shared automatically.": ["选择包含的内容，不会自动分享任何信息。", "Pilih kandungan untuk disertakan. Tiada apa dikongsi secara automatik.", "சேர்க்க வேண்டியதைத் தேர்ந்தெடுக்கவும். எதுவும் தானாகப் பகிரப்படாது."], "Caller or sender details": ["来电者或发送者资料", "Butiran pemanggil atau pengirim", "அழைப்பாளர் அல்லது அனுப்புநர் விவரங்கள்"], "Unknown caller · identifier not available": ["未知来电者 · 无标识资料", "Pemanggil tidak dikenali · pengecam tiada", "அறியாத அழைப்பாளர் · அடையாளம் கிடைக்கவில்லை"], "Message sender · identifier not supplied": ["信息发送者 · 未提供标识", "Pengirim mesej · pengecam tidak diberikan", "செய்தி அனுப்புநர் · அடையாளம் வழங்கப்படவில்லை"], "Warning reasons": ["提醒原因", "Sebab amaran", "எச்சரிக்கைக் காரணங்கள்"], "Include an excerpt (optional)": ["包含节选（可选）", "Sertakan petikan (pilihan)", "உரைப் பகுதியைச் சேர் (விருப்பம்)"], "Review and remove personal details. No audio is attached.": ["检查并移除个人资料，不附带音频。", "Semak dan buang butiran peribadi. Tiada audio dilampirkan.", "தனிப்பட்ட விவரங்களைச் சரிபார்த்து நீக்கவும். ஒலி இணைக்கப்படாது."], "Reviewed excerpt": ["已检查的节选", "Petikan disemak", "மதிப்பாய்வு செய்த உரைப் பகுதி"], "Type the excerpt you choose to include": ["输入您选择包含的节选", "Taip petikan yang ingin disertakan", "சேர்க்க விரும்பும் உரைப் பகுதியைத் தட்டச்சு செய்யவும்"], "Additional details (optional)": ["补充资料（可选）", "Butiran tambahan (pilihan)", "கூடுதல் விவரங்கள் (விருப்பம்)"], "Add relevant context": ["添加相关背景", "Tambah konteks berkaitan", "தொடர்புடைய சூழலைச் சேர்க்கவும்"], "Demonstration destination": ["演示接收方", "Destinasi demonstrasi", "செயல்விளக்கச் சேருமிடம்"], "Prototype review only. No police, bank or external service receives this report.": ["仅用于原型展示。警方、银行或外部服务均不会收到此举报。", "Untuk semakan prototaip sahaja. Tiada polis, bank atau perkhidmatan luar menerima laporan ini.", "முன்மாதிரி மதிப்பாய்வுக்கு மட்டுமே. காவல்துறை, வங்கி அல்லது வெளிச் சேவைக்கு இந்தப் புகார் செல்லாது."], "Confirm simulated submission": ["确认模拟提交", "Sahkan penghantaran simulasi", "உருவகச் சமர்ப்பிப்பை உறுதிசெய்"], "Cancel": ["取消", "Batal", "ரத்துசெய்"], "Reporting does not automatically end an active interaction.": ["举报不会自动结束进行中的互动。", "Pelaporan tidak menamatkan interaksi aktif secara automatik.", "புகாரளித்தல் நடக்கும் உரையாடலைத் தானாக முடிக்காது."], "Report submitted": ["举报已提交", "Laporan dihantar", "புகார் சமர்ப்பிக்கப்பட்டது"], "Simulated confirmation · no real report was sent.": ["模拟确认 · 未发送真实举报。", "Pengesahan simulasi · tiada laporan sebenar dihantar.", "உருவக உறுதிப்படுத்தல் · உண்மைப் புகார் அனுப்பப்படவில்லை."], "Additional details": ["补充资料", "Butiran tambahan", "கூடுதல் விவரங்கள்"], "Included in this demo": ["本次演示包含内容", "Disertakan dalam demo ini", "இந்த விளக்கத்தில் சேர்க்கப்பட்டவை"], "No optional fields selected.": ["未选择可选字段。", "Tiada medan pilihan dipilih.", "விருப்பப் புலங்கள் தேர்ந்தெடுக்கப்படவில்லை."], "Your reviewed excerpt": ["您检查后的节选", "Petikan yang anda semak", "நீங்கள் மதிப்பாய்வு செய்த உரைப் பகுதி"], "The simulated interaction is still active.": ["模拟互动仍在进行中。", "Interaksi simulasi masih aktif.", "உருவக உரையாடல் இன்னும் நடக்கிறது."], "No interaction is active.": ["目前没有进行中的互动。", "Tiada interaksi aktif.", "உரையாடல் எதுவும் நடைபெறவில்லை."], "Return to interaction": ["返回互动", "Kembali ke interaksi", "உரையாடலுக்குத் திரும்பு"], "Was this helpful?": ["这有帮助吗？", "Adakah ini membantu?", "இது உதவியாக இருந்ததா?"], "Your feedback is optional and separate from reporting.": ["反馈为可选项，与举报分开处理。", "Maklum balas adalah pilihan dan berasingan daripada laporan.", "கருத்து தெரிவிப்பது விருப்பமானது; புகாரிலிருந்து தனியானது."], "What would be shared": ["将分享的内容", "Apa yang akan dikongsi", "பகிரப்படவிருப்பது"], "Only your selected response. No call audio, transcript or message text is attached.": ["仅包含您选择的回复，不附带通话音频、文字记录或信息内容。", "Hanya jawapan dipilih. Tiada audio panggilan, transkrip atau teks mesej dilampirkan.", "நீங்கள் தேர்ந்தெடுத்த பதில் மட்டும். அழைப்பு ஒலி, உரைப் பதிவு அல்லது செய்தி இணைக்கப்படாது."], "Helpful": ["有帮助", "Membantu", "உதவியாக இருந்தது"], "Seems incorrect": ["似乎不正确", "Nampak tidak tepat", "தவறாகத் தெரிகிறது"], "Not sure": ["不确定", "Tidak pasti", "உறுதியாகத் தெரியவில்லை"], "Skip": ["跳过", "Langkau", "தவிர்"], "Review your feedback": ["检查您的反馈", "Semak maklum balas anda", "உங்கள் கருத்தை மதிப்பாய்வு செய்யவும்"], "Confirm before recording your response.": ["记录回复前请确认。", "Sahkan sebelum merekod jawapan anda.", "பதிலைப் பதிவுசெய்யும் முன் உறுதிசெய்யவும்."], "Your response": ["您的回复", "Jawapan anda", "உங்கள் பதில்"], "Separate from model training": ["与模型训练分开", "Berasingan daripada latihan model", "மாதிரிப் பயிற்சியிலிருந்து தனியானது"], "Feedback would be reviewed before informing future improvements. It would not automatically retrain a model.": ["反馈经审查后才用于改进，不会自动重新训练模型。", "Maklum balas akan disemak sebelum digunakan untuk penambahbaikan. Ia tidak melatih semula model secara automatik.", "மேம்பாட்டிற்குப் பயன்படுத்தும் முன் கருத்துகள் மதிப்பாய்வு செய்யப்படும். மாதிரி தானாக மீண்டும் பயிற்சி பெறாது."], "Confirm feedback": ["确认反馈", "Sahkan maklum balas", "கருத்தை உறுதிசெய்"], "This demo records feedback only in browser memory.": ["演示仅在浏览器内存中记录反馈。", "Demo ini merekod maklum balas dalam ingatan pelayar sahaja.", "இந்த விளக்கம் உலாவி நினைவகத்தில் மட்டுமே கருத்தைப் பதிகிறது."], "Feedback recorded": ["反馈已记录", "Maklum balas direkod", "கருத்து பதிவுசெய்யப்பட்டது"], "Thank you for reviewing the assessment.": ["感谢您评价此次分析。", "Terima kasih kerana menyemak penilaian ini.", "மதிப்பீட்டை மதிப்பாய்வு செய்ததற்கு நன்றி."], "Response": ["回复", "Jawapan", "பதில்"], "No feedback was transmitted. Your response exists only in this browser session.": ["反馈未发送，回复仅存在于本次浏览器会话。", "Tiada maklum balas dihantar. Jawapan hanya wujud dalam sesi pelayar ini.", "கருத்து அனுப்பப்படவில்லை. உங்கள் பதில் இந்த உலாவி அமர்வில் மட்டுமே உள்ளது."], "Control how supported protection works.": ["控制受支持防护的运行方式。", "Kawal cara perlindungan disokong berfungsi.", "ஆதரிக்கப்படும் பாதுகாப்பின் செயல்பாட்டைக் கட்டுப்படுத்துங்கள்."], "Supported live protection": ["受支持的实时防护", "Perlindungan langsung disokong", "ஆதரிக்கப்படும் நேரடிப் பாதுகாப்பு"], "Enable with consent first": ["请先同意并启用", "Aktifkan dengan persetujuan dahulu", "முதலில் ஒப்புதலுடன் இயக்கவும்"], "Paused": ["已暂停", "Dijeda", "இடைநிறுத்தப்பட்டது"], "Enabled for supported channels": ["已为受支持渠道启用", "Diaktifkan untuk saluran disokong", "ஆதரிக்கப்படும் வழிகளுக்கு இயக்கப்பட்டது"], "Sound alerts": ["声音提醒", "Amaran bunyi", "ஒலி எச்சரிக்கைகள்"], "Vibration alerts": ["振动提醒", "Amaran getaran", "அதிர்வு எச்சரிக்கைகள்"], "Preferred language": ["界面语言", "Bahasa pilihan", "விருப்ப மொழி"], "Interface language changes throughout the demo. Detection uses illustrative rules, not a multilingual AI model.": ["语言设置应用于整个演示。检测使用示例规则，并非多语言人工智能模型。", "Bahasa antara muka berubah di seluruh demo. Pengesanan menggunakan peraturan contoh, bukan model AI berbilang bahasa.", "செயல்விளக்கம் முழுவதும் இடைமுக மொழி மாறும். கண்டறிதல் எடுத்துக்காட்டு விதிகளைப் பயன்படுத்துகிறது; பன்மொழி AI மாதிரியை அல்ல."], "Working audio and transcripts would be discarded when no longer required.": ["不再需要时将删除处理中的音频及文字记录。", "Audio dan transkrip kerja akan dipadam apabila tidak diperlukan.", "தேவை முடிந்ததும் செயலாக்க ஒலியும் உரைப் பதிவுகளும் நீக்கப்படும்."], "Optional reporting": ["自愿举报", "Pelaporan pilihan", "விருப்பப் புகாரளித்தல்"], "Select and review information before a simulated submission.": ["模拟提交前选择并检查资料。", "Pilih dan semak maklumat sebelum penghantaran simulasi.", "உருவகச் சமர்ப்பிப்புக்கு முன் தகவலைத் தேர்ந்தெடுத்து மதிப்பாய்வு செய்யவும்."], "Optional payment reminder": ["可选付款提醒", "Peringatan bayaran pilihan", "விருப்பப் பண எச்சரிக்கை"], "Separate opt-in. Simulates an agreed bank integration.": ["单独同意启用，模拟获协议的银行集成。", "Persetujuan berasingan. Mensimulasikan integrasi bank yang dipersetujui.", "தனியான ஒப்புதல். ஒப்புக்கொள்ளப்பட்ட வங்கி ஒருங்கிணைப்பை உருவகப்படுத்துகிறது."], "Protection updates": ["防护更新", "Kemas kini perlindungan", "பாதுகாப்புப் புதுப்பிப்புகள்"], "Proposed release process: reviewed model and scam-list updates. No model or updates are downloaded in this demonstration.": ["拟议流程：模型和诈骗名单更新经审核后发布。此演示不会下载模型或更新。", "Proses cadangan: kemas kini model dan senarai penipuan disemak. Tiada model atau kemas kini dimuat turun dalam demo ini.", "முன்மொழியப்பட்ட நடைமுறை: மாதிரி மற்றும் மோசடிப் பட்டியல் புதுப்பிப்புகள் மதிப்பாய்வு செய்யப்படும். இந்த விளக்கத்தில் மாதிரியோ புதுப்பிப்போ பதிவிறக்கப்படாது."], "Preview warning languages": ["预览各语言提醒", "Pratonton bahasa amaran", "எச்சரிக்கை மொழிகளின் முன்னோட்டம்"], "Save preferences": ["保存设置", "Simpan pilihan", "விருப்பங்களைச் சேமி"], "Warnings people understand": ["易于理解的提醒", "Amaran yang difahami", "புரியக்கூடிய எச்சரிக்கைகள்"], "Illustrative language previews · translations require review before use.": ["语言示例 · 使用前需审核译文。", "Pratonton bahasa contoh · terjemahan perlu disemak sebelum digunakan.", "மொழி முன்னோட்டங்கள் · பயன்பாட்டிற்கு முன் மொழிபெயர்ப்பை மதிப்பாய்வு செய்யவும்."], "Pause before paying. Verify this request through an official channel.": ["付款前请暂停。请通过官方渠道核实这项要求。", "Berhenti seketika sebelum membuat bayaran. Sahkan permintaan ini melalui saluran rasmi.", "பணம் செலுத்தும் முன் சற்று நிறுத்துங்கள். அதிகாரப்பூர்வ வழியில் இந்தக் கோரிக்கையைச் சரிபார்க்கவும்."], "Singlish scenario": ["新加坡式英语情境", "Senario Singlish", "சிங்லிஷ் சூழல்"], "“Must transfer now, cannot tell anyone lah.” The concern is the combined payment pressure and secrecy, not the use of Singlish.": ["“Must transfer now, cannot tell anyone lah.” 风险在于付款压力和保密要求同时出现，而非使用新加坡式英语。", "“Must transfer now, cannot tell anyone lah.” Kebimbangannya ialah gabungan tekanan bayaran dan kerahsiaan, bukan penggunaan Singlish.", "“Must transfer now, cannot tell anyone lah.” பண அழுத்தமும் இரகசியமும் இணைவதே கவலைக்குரியது; சிங்லிஷ் பயன்பாடு அல்ல."], "Back to settings": ["返回设置", "Kembali ke tetapan", "அமைப்புகளுக்குத் திரும்பு"], "These previews do not demonstrate multilingual model performance.": ["这些预览不代表多语言模型的性能。", "Pratonton ini tidak menunjukkan prestasi model berbilang bahasa.", "இந்த முன்னோட்டங்கள் பன்மொழி மாதிரிச் செயல்திறனைக் காட்டுவதில்லை."], "Know your coverage": ["了解防护范围", "Ketahui liputan anda", "உங்கள் பாதுகாப்பு வரம்பை அறியுங்கள்"], "Support depends on permissions and integration.": ["支持情况取决于权限及集成。", "Sokongan bergantung pada kebenaran dan integrasi.", "ஆதரவு அனுமதிகளையும் ஒருங்கிணைப்பையும் சார்ந்தது."], "Supported calling integration": ["受支持的通话集成", "Integrasi panggilan disokong", "ஆதரிக்கப்படும் அழைப்பு ஒருங்கிணைப்பு"], "Available only when authorised access to the call content is provided.": ["仅在获授权访问通话内容后可用。", "Hanya tersedia apabila akses sah kepada kandungan panggilan diberikan.", "அழைப்பு உள்ளடக்கத்திற்கு அங்கீகரிக்கப்பட்ட அணுகல் வழங்கப்பட்டால் மட்டுமே கிடைக்கும்."], "Other apps or call channels": ["其他应用或通话渠道", "Aplikasi atau saluran panggilan lain", "பிற செயலிகள் அல்லது அழைப்பு வழிகள்"], "Live analysis may be unavailable. This demo cannot access actual calls.": ["实时分析可能不可用，此演示无法访问真实通话。", "Analisis langsung mungkin tidak tersedia. Demo ini tidak boleh mengakses panggilan sebenar.", "நேரடிப் பகுப்பாய்வு கிடைக்காமல் இருக்கலாம். இந்த விளக்கத்தால் உண்மையான அழைப்புகளை அணுக முடியாது."], "Voluntary message checking": ["自愿检查信息", "Semakan mesej sukarela", "விருப்பச் செய்திச் சோதனை"], "You can submit message text manually for a separate assessment.": ["可手动输入信息以单独分析。", "Anda boleh memasukkan teks mesej secara manual untuk penilaian berasingan.", "தனியான மதிப்பீட்டிற்குச் செய்தி உரையை கைமுறையாக உள்ளிடலாம்."], "Check a message instead": ["改为检查信息", "Semak mesej sebagai alternatif", "அதற்குப் பதிலாக செய்தியைச் சரிபார்"], "Do not assume an unsupported interaction has been checked.": ["请勿假定不受支持的互动已接受检查。", "Jangan anggap interaksi tidak disokong telah disemak.", "ஆதரிக்கப்படாத உரையாடல் சரிபார்க்கப்பட்டது எனக் கருத வேண்டாம்."], "Pause before paying": ["付款前先暂停", "Berhenti sebelum membayar", "பணம் செலுத்தும் முன் நிறுத்துங்கள்"], "Optional bank-partner integration · concept only": ["可选银行合作集成 · 仅为概念", "Integrasi rakan bank pilihan · konsep sahaja", "விருப்ப வங்கிக் கூட்டாளர் ஒருங்கிணைப்பு · கருத்தாக்கம் மட்டும்"], "Recent conversation risk": ["近期对话风险", "Risiko perbualan terkini", "சமீப உரையாடல் இடர்"], "A supported conversation involved secrecy and pressure to transfer money.": ["受支持的对话涉及保密要求及转账压力。", "Perbualan disokong melibatkan kerahsiaan dan tekanan memindahkan wang.", "ஆதரிக்கப்படும் உரையாடலில் இரகசியமும் பணம் மாற்றும் அழுத்தமும் இருந்தன."], "Verify the request": ["核实要求", "Sahkan permintaan", "கோரிக்கையைச் சரிபார்க்கவும்"], "Use an official contact channel before proceeding with a payment.": ["付款前通过官方联络渠道核实。", "Gunakan saluran hubungan rasmi sebelum meneruskan bayaran.", "பணம் செலுத்தும் முன் அதிகாரப்பூர்வத் தொடர்பு வழியைப் பயன்படுத்தவும்."], "Your decision stays yours": ["决定权始终在您手中", "Keputusan kekal milik anda", "முடிவு உங்களுடையதே"], "This assistant has not blocked a transfer or accessed a bank account.": ["此助手未阻止转账，也未访问银行账户。", "Pembantu ini tidak menyekat pindahan atau mengakses akaun bank.", "இந்த உதவியாளர் பரிமாற்றத்தைத் தடுக்கவோ வங்கிக் கணக்கை அணுகவோ இல்லை."], "Return to demonstrations": ["返回演示", "Kembali ke demonstrasi", "செயல்விளக்கங்களுக்குத் திரும்பு"], "Review payment reminder opt-in": ["查看付款提醒同意选项", "Semak persetujuan peringatan bayaran", "பண எச்சரிக்கை ஒப்புதலை மதிப்பாய்வு செய்"], "Requires separate user agreement and an agreed bank integration. No banking or payment function exists in this prototype.": ["需要用户单独同意及银行集成协议。本原型没有真实银行或付款功能。", "Memerlukan persetujuan pengguna berasingan dan integrasi bank dipersetujui. Prototaip ini tiada fungsi bank atau bayaran.", "தனியான பயனர் ஒப்புதலும் ஒப்புக்கொள்ளப்பட்ட வங்கி ஒருங்கிணைப்பும் தேவை. இந்த முன்மாதிரியில் வங்கிச் செயலோ பணம் செலுத்துதலோ இல்லை."], "“Safe account” transfer": ["“安全账户”转账", "Pindahan “akaun selamat”", "“பாதுகாப்புக் கணக்கு” பரிமாற்றம்"], "The message asks for a transfer to an account presented as protecting your money.": ["信息要求转账到声称能保护资金的账户。", "Mesej meminta pindahan ke akaun yang dikatakan melindungi wang anda.", "உங்கள் பணத்தைப் பாதுகாக்கும் எனக் கூறப்படும் கணக்கிற்கு மாற்றச் செய்தி கோருகிறது."], "Upfront or unusual payment": ["预付或异常付款", "Bayaran pendahuluan atau luar biasa", "முன்கட்டணம் அல்லது வழக்கமற்ற பணம்"], "A fee or unusual payment method is requested as part of the opportunity.": ["该机会要求支付费用或使用异常付款方式。", "Yuran atau kaedah bayaran luar biasa diminta sebagai sebahagian tawaran.", "வாய்ப்பின் பகுதியாகக் கட்டணமோ வழக்கமற்ற பணமுறையோ கோரப்படுகிறது."], "Urgency": ["紧迫感", "Desakan", "அவசரம்"], "The wording pressures you to act quickly.": ["措辞催促您快速行动。", "Kata-kata mendesak anda bertindak cepat.", "சொற்கள் உங்களை விரைந்து செயல்பட அழுத்துகின்றன."], "The sender discourages discussing the request or getting independent advice.": ["发送者不鼓励讨论要求或寻求独立建议。", "Pengirim menghalang perbincangan permintaan atau nasihat bebas.", "கோரிக்கையைப் பற்றிப் பேசவோ சுய ஆலோசனை பெறவோ அனுப்புநர் வேண்டாம் என்கிறார்."], "Assurance of returns": ["保证回报", "Jaminan pulangan", "வருமான உறுதி"], "An investment return is presented as guaranteed.": ["投资回报被描述为有保证。", "Pulangan pelaburan dikatakan dijamin.", "முதலீட்டு வருமானம் உறுதியானது எனக் கூறப்படுகிறது."], "Sensitive credentials": ["敏感验证资料", "Bukti kelayakan sensitif", "முக்கிய அங்கீகாரத் தகவல்"], "The message requests sensitive authentication information.": ["信息索取敏感身份验证资料。", "Mesej meminta maklumat pengesahan sensitif.", "செய்தி முக்கிய அங்கீகாரத் தகவலைக் கோருகிறது."], "Enable or resume protection to try a supported live conversation.": ["启用或恢复防护后体验受支持的实时对话。", "Aktifkan atau sambung perlindungan untuk mencuba perbualan langsung disokong.", "ஆதரிக்கப்படும் நேரடி உரையாடலை முயல பாதுகாப்பை இயக்கவும் அல்லது மீண்டும் தொடங்கவும்."], "Live protection paused": ["实时防护已暂停", "Perlindungan langsung dijeda", "நேரடிப் பாதுகாப்பு இடைநிறுத்தப்பட்டது"], "Live protection resumed": ["实时防护已恢复", "Perlindungan langsung disambung", "நேரடிப் பாதுகாப்பு மீண்டும் தொடங்கியது"], "Enter a message first": ["请先输入信息", "Masukkan mesej dahulu", "முதலில் செய்தியை உள்ளிடவும்"], "Enter a reviewed excerpt or unselect that field.": ["请输入检查后的节选，或取消选择该字段。", "Masukkan petikan disemak atau nyahpilih medan itu.", "மதிப்பாய்வு செய்த உரையை உள்ளிடவும் அல்லது புலத்தைத் தேர்வுநீக்கவும்."], "Preferences saved for this browser session": ["设置已保存至本次浏览器会话", "Pilihan disimpan untuk sesi pelayar ini", "இந்த உலாவி அமர்விற்கு விருப்பங்கள் சேமிக்கப்பட்டன"], "Restart the demonstration and clear session content?": ["重新开始演示并清除本次内容？", "Mulakan semula demo dan padam kandungan sesi?", "விளக்கத்தை மீண்டும் தொடங்கி அமர்வு உள்ளடக்கத்தை அழிக்கவா?"], "Language previews": ["语言预览", "Pratonton bahasa", "மொழி முன்னோட்டங்கள்"], "Informed activation": ["知情启用", "Pengaktifan bermaklumat", "தகவலறிந்த இயக்கம்"], "Coverage is visible": ["防护范围清晰可见", "Liputan jelas", "தெளிவான பாதுகாப்பு வரம்பு"], "Different scenarios, different reasons": ["不同情境，不同原因", "Senario berbeza, sebab berbeza", "வெவ்வேறு சூழல்களும் காரணங்களும்"], "Context develops over time": ["上下文逐步形成", "Konteks berkembang", "காலப்போக்கில் உருவாகும் சூழல்"], "An actionable explanation": ["可采取行动的解释", "Penjelasan yang boleh ditindak", "செயல்பட உதவும் விளக்கம்"], "Choice without losing context": ["选择同时保留上下文", "Pilihan dengan konteks", "சூழலைத் தக்கவைக்கும் தேர்வு"], "Temporary processing ends": ["临时处理结束", "Pemprosesan sementara tamat", "தற்காலிகச் செயலாக்கம் முடிகிறது"], "An honest assessment": ["坦诚的分析结果", "Penilaian jujur", "நேர்மையான மதிப்பீடு"], "Review before sharing": ["分享前检查", "Semak sebelum berkongsi", "பகிரும் முன் மதிப்பாய்வு"], "Submission transparency": ["提交过程透明", "Ketelusan penghantaran", "வெளிப்படையான சமர்ப்பிப்பு"], "Feedback with consent": ["经同意后反馈", "Maklum balas dengan persetujuan", "ஒப்புதலுடன் கருத்து"], "Review optional feedback": ["检查可选反馈", "Semak maklum balas pilihan", "விருப்பக் கருத்தை மதிப்பாய்வு செய்"], "A separate feedback path": ["独立反馈渠道", "Laluan maklum balas berasingan", "தனியான கருத்துப் பாதை"], "Meaningful user controls": ["实用的用户控制", "Kawalan pengguna bermakna", "பயனுள்ள பயனர் கட்டுப்பாடுகள்"], "A visible limitation": ["明确说明限制", "Batasan yang jelas", "வெளிப்படையான வரம்பு"], "A conditional partner feature": ["需合作支持的功能", "Ciri rakan kongsi bersyarat", "நிபந்தனையுள்ள கூட்டாளர் அம்சம்"], "Coverage and consent are explained before enabling protection. The consent control gates activation.": ["启用前说明防护范围并征求同意，只有同意后才能启用。", "Liputan dan persetujuan dijelaskan sebelum perlindungan diaktifkan. Persetujuan diperlukan untuk pengaktifan.", "இயக்கும் முன் வரம்பும் ஒப்புதலும் விளக்கப்படும். ஒப்புதல் பெற்றால் மட்டுமே இயக்கப்படும்."], "The dashboard distinguishes supported call analysis from voluntary message checking. Pausing live analysis keeps manual checking available.": ["概览区分通话分析与自愿信息检查。暂停实时分析后仍可手动检查。", "Papan pemuka membezakan analisis panggilan dan semakan mesej sukarela. Semakan manual kekal tersedia apabila analisis dijeda.", "முகப்பு அழைப்புப் பகுப்பாய்வையும் விருப்பச் செய்திச் சோதனையையும் வேறுபடுத்துகிறது. நேரடிப் பகுப்பாய்வை நிறுத்தினாலும் கைமுறை சோதனை கிடைக்கும்."], "Try explicit impersonation, gradually developing investment pressure, a job-scam message or a legitimate interaction. These are demonstrations, not test results.": ["体验冒充身份、逐步施压的投资对话、求职诈骗或正常互动。这是演示，并非测试结果。", "Cuba penyamaran, tekanan pelaburan berperingkat, mesej penipuan kerja atau interaksi sah. Ini demonstrasi, bukan keputusan ujian.", "ஆள்மாறாட்டம், படிப்படியான முதலீட்டு அழுத்தம், வேலை மோசடி அல்லது முறையான உரையாடலை முயலுங்கள். இவை விளக்கங்கள்; சோதனை முடிவுகள் அல்ல."], "A normal opening is not proof of fraud. Later requests introduce urgency, secrecy and payment demands. The next-stage controls simulate this progression.": ["正常开场并非诈骗证据。后续要求引入紧迫、保密与付款要求。分阶段操作模拟此变化。", "Pembukaan biasa bukan bukti penipuan. Permintaan kemudian membawa desakan, kerahsiaan dan bayaran. Kawalan peringkat mensimulasikan perkembangan ini.", "சாதாரண தொடக்கம் மோசடிக்கான ஆதாரமல்ல. பின்னர் அவசரம், இரகசியம், பணக் கோரிக்கைகள் வரும். படிநிலைக் கட்டுப்பாடுகள் இதை உருவகப்படுத்துகின்றன."], "The warning identifies specific suspicious requests and preserves the user’s choice. No transfer is automatically blocked.": ["提醒指出具体可疑要求，并保留用户选择。不会自动阻止转账。", "Amaran mengenal pasti permintaan mencurigakan dan mengekalkan pilihan pengguna. Tiada pindahan disekat secara automatik.", "எச்சரிக்கை சந்தேகக் கோரிக்கைகளைக் குறிப்பிட்டு பயனர் தேர்வைத் தக்கவைக்கிறது. பரிமாற்றம் தானாகத் தடுக்கப்படாது."], "Continuing dismisses the immediate warning while the simulated interaction remains active. The warning can be reopened.": ["选择继续会关闭当前提醒，但模拟互动仍继续。可重新打开提醒。", "Meneruskan menutup amaran semasa sementara interaksi simulasi kekal aktif. Amaran boleh dibuka semula.", "தொடர்வது உடனடி எச்சரிக்கையை மூடும்; உருவக உரையாடல் தொடரும். எச்சரிக்கையை மீண்டும் திறக்கலாம்."], "The call ends in this demonstration. Working call content would be discarded when no longer needed. Reports remain separate.": ["演示中的通话结束。不再需要时将删除工作内容，举报另行处理。", "Panggilan tamat dalam demo ini. Kandungan kerja akan dipadam apabila tidak diperlukan. Laporan kekal berasingan.", "விளக்கத்தில் அழைப்பு முடிகிறது. தேவை முடிந்ததும் செயலாக்க உள்ளடக்கம் நீக்கப்படும். புகார்கள் தனியாக இருக்கும்."], "Type or paste text, or load an example. The demonstration runs simple local checks and never transmits entered content.": ["输入、粘贴文字或载入示例。演示进行简单本地检查，不会发送输入内容。", "Taip atau tampal teks, atau muat contoh. Demo menjalankan semakan setempat mudah tanpa menghantar kandungan.", "உரையை உள்ளிடவும், ஒட்டவும் அல்லது எடுத்துக்காட்டை ஏற்றவும். எளிய உள்ளூர்ச் சோதனைகள் நடக்கும்; உள்ளடக்கம் அனுப்பப்படாது."], "Explain indicators rather than invent an accuracy percentage. A result with no strong indicators is not a guarantee of safety.": ["解释风险迹象，不虚构准确率。未发现明显迹象不保证安全。", "Petunjuk dijelaskan tanpa peratus ketepatan rekaan. Tiada petunjuk kukuh bukan jaminan keselamatan.", "கற்பனைத் துல்லிய சதவீதமின்றி அறிகுறிகள் விளக்கப்படும். வலுவான அறிகுறிகள் இல்லாதது பாதுகாப்பு உத்தரவாதமல்ல."], "Select identity details, reasons and an optional excerpt. Unselected fields are excluded from the simulated report.": ["选择身份资料、原因及可选节选。未选字段不包含在模拟举报中。", "Pilih butiran identiti, sebab dan petikan pilihan. Medan tidak dipilih tidak disertakan dalam laporan simulasi.", "அடையாள விவரங்கள், காரணங்கள், விருப்ப உரைப் பகுதியைத் தேர்ந்தெடுக்கவும். தேர்வுசெய்யாதவை உருவகப் புகாரில் சேராது."], "This screen displays the exact selected fields. No real reporting service is contacted.": ["此界面显示所选字段，不会联系真实举报服务。", "Skrin ini memaparkan medan dipilih. Tiada perkhidmatan laporan sebenar dihubungi.", "தேர்ந்தெடுத்த புலங்கள் இங்கே காட்டப்படும். உண்மைப் புகார் சேவை தொடர்புகொள்ளப்படாது."], "A response can be reviewed before it is recorded in this browser session. It does not automatically retrain a model.": ["回复在本次会话记录前可供检查，不会自动重新训练模型。", "Jawapan boleh disemak sebelum direkod dalam sesi ini. Ia tidak melatih semula model secara automatik.", "இந்த அமர்வில் பதியும் முன் பதிலை மதிப்பாய்வு செய்யலாம். மாதிரி தானாக மீண்டும் பயிற்சி பெறாது."], "Only the chosen response is included; audio, messages and transcripts are not attached.": ["仅包含所选回复，不附带音频、信息或文字记录。", "Hanya jawapan dipilih disertakan; audio, mesej dan transkrip tidak dilampirkan.", "தேர்ந்தெடுத்த பதில் மட்டும் சேரும்; ஒலி, செய்திகள், உரைப் பதிவுகள் இணைக்கப்படாது."], "Feedback and reporting are distinct. The prototype records this response only in memory.": ["反馈与举报分开，原型仅在内存记录回复。", "Maklum balas dan laporan berasingan. Prototaip merekod jawapan dalam ingatan sahaja.", "கருத்தும் புகாரும் தனித்தனியானவை. முன்மாதிரி பதிலை நினைவகத்தில் மட்டுமே பதியும்."], "Pause live protection, set alert preferences and choose the language for the whole interface.": ["暂停实时防护、设置提醒偏好，并选择整个界面的语言。", "Jeda perlindungan langsung, tetapkan amaran dan pilih bahasa seluruh antara muka.", "நேரடிப் பாதுகாப்பை இடைநிறுத்தவும், எச்சரிக்கைகளை அமைக்கவும், முழு இடைமுக மொழியைத் தேர்ந்தெடுக்கவும்."], "The assistant cannot assume access to every call or messaging app. Channel limitations are shown rather than hidden.": ["助手并非能访问所有通话或信息应用。界面会明确显示渠道限制。", "Pembantu tidak boleh menganggap akses kepada semua panggilan atau aplikasi mesej. Batasan saluran dipaparkan dengan jelas.", "அனைத்து அழைப்புகளையும் செய்திச் செயலிகளையும் உதவியாளர் அணுக முடியாது. வழிகளின் வரம்புகள் தெளிவாகக் காட்டப்படும்."], "An advisory banking-stage warning assumes an agreed integration. This prototype has no access to banking activity.": ["银行阶段提醒以协议集成为前提。本原型无法访问银行活动。", "Amaran peringkat bank memerlukan integrasi dipersetujui. Prototaip ini tidak mengakses aktiviti bank.", "வங்கிநிலை எச்சரிக்கை ஒப்புக்கொள்ளப்பட்ட ஒருங்கிணைப்பைச் சார்ந்தது. முன்மாதிரி வங்கி நடவடிக்கைகளை அணுகாது."], "Sample warning wording demonstrates the intended interface. Language detection and translation quality are not validated.": ["提醒措辞示例用于展示界面。语言检测及翻译质量尚未验证。", "Contoh amaran menunjukkan antara muka cadangan. Pengesanan bahasa dan mutu terjemahan belum disahkan.", "எடுத்துக்காட்டு எச்சரிக்கை இடைமுகத்தைக் காட்டுகிறது. மொழி கண்டறிதலும் மொழிபெயர்ப்புத் தரமும் சரிபார்க்கப்படவில்லை."]};

const nativeNames={English:'English',Mandarin:'中文',Malay:'Bahasa Melayu',Tamil:'தமிழ்'};
const langCodes={English:'en',Mandarin:'zh-Hans',Malay:'ms',Tamil:'ta'};
try{const saved=localStorage.getItem('scam-alert-language');if(nativeNames[saved])S.language=saved}catch{}
function tr(value){const i=['Mandarin','Malay','Tamil'].indexOf(S.language);return i<0?value:(translations[value]?.[i]??value)}
const originalText=new WeakMap();
function localize(){
 document.documentElement.lang=langCodes[S.language];document.title=tr('Scam Alert')+' · '+tr('Interactive demo');
 const global=document.getElementById('globalLanguage');if(global)global.value=S.language;
 const walk=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
 let n;while(n=walk.nextNode()){
  const parent=n.parentElement;if(!parent||parent.closest('script,style,textarea,select,[data-user-content]'))continue;
  if(!originalText.has(n))originalText.set(n,n.nodeValue);
  const raw=originalText.get(n),key=raw.trim();
  let value=tr(key);if(value===key&&key.includes(' · '))value=key.split(' · ').map(tr).join(' · ');
  // Dynamic status lines combine a scenario name, a step counter and a label.
  if(value===key){for(const [english,names] of Object.entries(translations)){if(key.startsWith(english+' · '))value=tr(english)+key.slice(english.length).replace(/ · (.+)$/,(_,tail)=>' · '+tr(tail));}
   value=value.replace(/Step (\d+) of 3/g,(_,v)=>({Mandarin:`第 ${v} 步，共 3 步`,Malay:`Langkah ${v} daripada 3`,Tamil:`3 இல் படிநிலை ${v}`}[S.language]||`Step ${v} of 3`));
  }
  n.nodeValue=raw.replace(key,value);
 }
 for(const node of document.querySelectorAll('[placeholder],[aria-label]')){
  for(const attr of ['placeholder','aria-label'])if(node.hasAttribute(attr)){
   const dataKey='i18n'+attr.replace('-','');if(!node.dataset[dataKey])node.dataset[dataKey]=node.getAttribute(attr);
   node.setAttribute(attr,tr(node.dataset[dataKey]));
  }
 }
 const label=document.getElementById('screenName');const names={setup:'Get started',dashboard:'Protection dashboard',scenarios:'Try scenarios',conversation:'Supported conversation',warning:'Pause and verify',ongoing:'Interaction in progress',ended:'Interaction ended',message:'Check a message',result:'Illustrative local assessment',report:'Review your report',confirmation:'Report submitted',feedback:'Was this helpful?',feedbackReview:'Review your feedback',feedbackDone:'Feedback recorded',settings:'Privacy & settings',coverage:'Know your coverage',bank:'Pause before paying',languages:'Language previews'};if(label)label.textContent=tr(names[S.page]||'Scam Alert');
}
const renderEnglish=render;render=function(){renderEnglish();localize()};
const toastEnglish=toast;toast=function(message){toastEnglish(tr(message))};
const nativeConfirm=window.confirm.bind(window);window.confirm=message=>nativeConfirm(tr(message));
const initialPage=location.hash.slice(1);if(info[initialPage]){S.page=initialPage;if(initialPage==='result'){S.message=job;S.result=assess(job);}}render();